    public static (string Prenom, string Nom) Generer(string race, string sexe)
    {
        string raceNoms = race == "Haut-Elfe" ? "Elfe gris" : race;
        string genre = sexe == "F" ? "F" : "H";
        if (!Groupes.TryGetValue(raceNoms + "|" + genre, out string[] prenoms) &&
            !Groupes.TryGetValue(raceNoms + "|Tous", out prenoms))
            throw new ArgumentException("Base des prénoms inconnue : " + raceNoms);

        string prenom = prenoms[Random.Shared.Next(prenoms.Length)];
        string nom = Groupes.TryGetValue(raceNoms + "|Nom", out string[] noms)
            ? noms[Random.Shared.Next(noms.Length)]
            : "";
        return (prenom, nom);
    }
